section.artwork:
"extensions": {
  "composed/v1": {
    "members": [
      { "id": "<member id>", "observer": "<observer id>",
        "request_digest": "<64 hex>", "outcome": "artifact",
        "digest": "<64 hex>", "bundle": { ... } },
      { "id": "<member id>", "observer": "<observer id>",
        "request_digest": "<64 hex>", "outcome": "refusal",
        "digest": "<64 hex>", "refusal": { ... } }
    ],
    "observers": [
      { "id": "<observer id>", "role": "<role>",
        "custody_domain": "<label>" }
    ],
    "joins": [
      { "members": ["<member id>", "<member id>"],
        "basis": "pre_agreed_identifier",
        "pointer": "<JSON Pointer>",
        "identifier_digest": "<64 hex>",
        "compare": ["<JSON Pointer>"],
        "state": "agree" }
    ],
    "not_requested": [ "<participant id>" ],
    "missing": [ "<member id>" ],
    "composed_digest": "<64 hex>"
  }
}

section.sourcecode:
composed-v1 = { members: [+ composed-member], observers: [+ composed-observer], ? joins: [* composed-join], ? not_requested: [* label-id], ? missing: [* label-id], composed_digest: digest-hex, }
composed-member = artifact-member / refusal-member / absence-member
member-common = ( id: label-id, observer: label-id, ; an observers[].id request_digest: digest-hex, ; the Evidence Request this answers digest: digest-hex, ; see "Members and Outcomes" )
artifact-member = { member-common, outcome: "artifact", ? bundle: { * tstr => any } } ; a Bundle refusal-member = { member-common, outcome: "refusal", ? refusal: signed-refusal } absence-member = { member-common, outcome: "absence", ? absence: recorded-absence }
signed-refusal = { ; as received, unmodified request_digest: digest-hex, reason: tstr, ; Evidence Request refusal reason issued_at: tstr, ; RFC 3339 * tstr => any, ; deployment signature members }
recorded-absence = { ; the requester's own record request_digest: digest-hex, window: { from: tstr, to: tstr }, ; RFC 3339 ? route: tstr, ? commitment: digest-hex, ; a retention commitment it held }
composed-observer = { id: label-id, role: tstr, ; see "Observers and Redundancy" custody_domain: tstr, ; opaque, compared octet-for-octet }
composed-join = { members: [label-id, label-id], ; two distinct ids, ascending basis: join-basis, ? pointer: tstr, ; RFC 6901 JSON Pointer ? identifier_digest: digest-hex, ? compare: [+ tstr], ; RFC 6901 JSON Pointers state: join-state, }
join-basis = "pre_agreed_identifier" / "shared_artifact_digest" / "issued_receipt" / "same_interval" join-state = "agree" / "mismatch" / "unjoined" / "one_sided"
label-id = text .regexp "[A-Za-z0-9._:-]{1,128}" digest-hex = text .regexp "[0-9a-f]{64}"

section.artwork:
{
  "type": "countersign/v1",
  "signer": { "id": "<signer identifier>", "key_id": "<64 hex>" },
  "over": "<bundle digest>",
  "statement": {
    "checks": [ {"name": "<check>", "result": "<result>"}, ... ],
    "recomputed_at": "<RFC 3339 UTC timestamp>",
    "scope": {
      "ledger_id": "<ledger identifier>",
      "period": { "from": "<RFC 3339>", "to": "<RFC 3339>" },
      "closure_depth": 2
    }
  },
  "signature": "<128 hex>",
  "receipt": { ... }
}

li.t:
recompute the bundle digest and compare it to over. An entry whose over
differs is not a countersignature of this Bundle and MUST be reported as
invalid;

verify signature over the signing input under signer.key_id. An entry
whose signature fails is invalid, and its checks MUST NOT be displayed as
results;
